mapper.select:
SELECT /*SQL-ID : isry.couns.constt.etcntabrd.mapper.BbsMomtListMapper : 자녀맘터치법(조회)답변완료*/ EE.BBSCTT_ESNTAL_NO AS BBSCTT_ESNTAL_NO , CASE WHEN EE.NUM = '2' THEN 'RE: ' || EE.BBSCTT_CN ELSE EE.BBSCTT_CN END AS BBSCTT_CN , EE.BBSCTT_TTL_NM AS BBSCTT_TTL_NM , EE.WRTR_NM_ENCPT AS WRTR_NM_ENCPT , EE.CONSTT_NM_ENCPT AS CONSTT_NM_ENCPT , EE.FRST_RGTR_ID AS FRST_RGTR_ID , TO_CHAR(EE.FRST_REG_DT, 'YYYY-MM-DD') AS FRST_REG_DT , EE.NUM AS NUM , EE.RETE_ESNTAL_NO AS RETE_ESNTAL_NO , COUNT(*) OVER() AS TOTAL_COUNT FROM ( SELECT AA.BBSCTT_CN AS BBSCTT_CN , AA.BBSCTT_ESNTAL_NO AS BBSCTT_ESNTAL_NO , AA.BBSCTT_TTL_NM AS BBSCTT_TTL_NM , AA.FRST_RGTR_ID AS FRST_RGTR_ID , AA.WRTR_NM_ENCPT AS WRTR_NM_ENCPT , AA.FRST_REG_DT AS FRST_REG_DT , BB.RETE_ESNTAL_NO AS RETE_ESNTAL_NO , ( SELECT A1.CONSTT_NM_ENCPT FROM AYA150 A1 WHERE 1=1 AND A1.BBSCTT_TYPE_SE_CD = '15' AND A1.BBSCTT_ESNTAL_NO = AA.BBSCTT_ESNTAL_NO ) AS CONSTT_NM_ENCPT , '1' AS NUM FROM AYE100 AS AA ,AYE120 AS BB WHERE 1=1 AND BB.BBSCTT_TYPE_SE_CD = '15' AND AA.DEL_YN = 'N' AND BB.DEL_YN = 'N' AND BB.BBSCTT_TYPE_SE_CD = AA.BBSCTT_TYPE_SE_CD AND AA.BBSCTT_ESNTAL_NO = BB.BBSCTT_ESNTAL_NO
AND ( SELECT A1.CONSTT_ID FROM AYA150 A1 WHERE 1=1 AND A1.BBSCTT_TYPE_SE_CD = '15' AND A1.BBSCTT_ESNTAL_NO = AA.BBSCTT_ESNTAL_NO ) = #{LOGIN_ID}
AND AA.BBSCTT_TTL_NM LIKE '%'||#{BBSCTT_TTL_NM}||'%'
AND AA.WRTR_NM_ENCPT LIKE '%'||#{WRTR_NM_ENCPT}||'%'
AND AA.BBSCTT_ESNTAL_NO = #{BBSCTT_ESNTAL_NO}
AND AA.CRISIS_TYPE_SE_CD = #{CRISIS_TYPE_SE_CD}
AND AA.FRST_REG_DT >= TO_DATE(#{STARTDATE} || '000000', 'YYYYMMDDHH24MISS')
AND AA.FRST_REG_DT < TO_DATE(#{ENDDATE} || '000000', 'YYYYMMDDHH24MISS')+1
UNION ALL SELECT BB.RETE_CN AS BBSCTT_CN , BB.BBSCTT_ESNTAL_NO AS BBSCTT_ESNTAL_NO , BB.RETE_TTL_NM AS BBSCTT_TTL_NM , BB.FRST_RGTR_ID AS FRST_RGTR_ID , BB.WRTR_NM_ENCPT AS WRTR_NM_ENCPT , BB.FRST_REG_DT AS FRST_REG_DT , BB.RETE_ESNTAL_NO AS RETE_ESNTAL_NO , '' AS CONSTT_NM_ENCPT , '2' AS NUM FROM AYE120 AS BB ,AYE100 AS AA WHERE 1=1 AND BB.BBSCTT_TYPE_SE_CD = '15' AND BB.DEL_YN = 'N' AND AA.DEL_YN = 'N' AND BB.BBSCTT_TYPE_SE_CD = AA.BBSCTT_TYPE_SE_CD AND AA.BBSCTT_ESNTAL_NO = BB.BBSCTT_ESNTAL_NO
AND AA.CRISIS_TYPE_SE_CD = #{CRISIS_TYPE_SE_CD}
AND ( SELECT A1.CONSTT_ID FROM AYA150 A1 WHERE 1=1 AND A1.BBSCTT_TYPE_SE_CD = '15' AND A1.BBSCTT_ESNTAL_NO = AA.BBSCTT_ESNTAL_NO ) = #{LOGIN_ID}
AND AA.BBSCTT_TTL_NM LIKE '%'||#{BBSCTT_TTL_NM}||'%' /*게시글제목명*/
AND BB.WRTR_NM_ENCPT LIKE '%'||#{WRTR_NM_ENCPT}||'%' /*작성자명*/
AND BB.BBSCTT_ESNTAL_NO = #{BBSCTT_ESNTAL_NO} /*게시글번호*/
AND BB.FRST_REG_DT >= TO_DATE(#{STARTDATE} || '000000', 'YYYYMMDDHH24MISS')
AND BB.FRST_REG_DT < TO_DATE(#{ENDDATE} || '000000', 'YYYYMMDDHH24MISS')+1
) AS EE ORDER BY EE.BBSCTT_ESNTAL_NO ASC , EE.NUM OFFSET #{START_IDX} ROWS FETCH NEXT #{ROW_COUNT} ROWS ONLY

mapper.update:
/*SQL-ID : isry.couns.constt.medscsnntabrd.mapper.BbsmomListMapper :  자녀맘터치법(조회수)*/
UPDATE AYE100 SET
    RDCNT_NOCS = NVL(TO_NUMBER(RDCNT_NOCS), 0) +1
WHERE 1=1
AND BBSCTT_TYPE_SE_CD = '15'
AND BBSCTT_ESNTAL_NO = #{BBSCTT_ESNTAL_NO}

UPDATE AYE100 SET
            /*SQL-ID : isry.couns.constt.medscsnntabrd.mapper.BbsmomListMapper :  자녀맘터치법(삭제)*/
              DEL_YN = 'Y'
            , LAST_MDFCN_DT = SYSDATE     
            , LAST_MDFR_ID = #{LAST_MDFR_ID}
WHERE       1=1
    AND     BBSCTT_TYPE_SE_CD = '15'
    AND     BBSCTT_ESNTAL_NO = #{BBSCTT_ESNTAL_NO__origin}

mapper.insert:
SELECT AYE120_SQ01.CURRVAL AS RETE_ESNTAL_NO FROM DUAL
INSERT INTO AYE120 (/*SQL-ID : isry.couns.constt.medscsnntabrd.mapper.BbsmomListMapper : 자녀맘터치법(답글추가)*/ FRST_RGTR_ID /*작성자아이디*/ , WRTR_NM_ENCPT /*작성자명*/ , CNTN_IP_ADDR /*아이피*/ , RETE_CN /*답글내용*/ , BBSCTT_ESNTAL_NO /*게시글번호*/ , BBSCTT_TYPE_SE_CD /*게시글유형구분코드*/ , RETE_ESNTAL_NO /*답글고유번호*/ , RETE_TTL_NM /*답글제목*/
, ATFINO /*첨부파일명*/
) VALUES ( #{FRST_RGTR_ID} /*작성자아이디*/ , C##RG.ENC_B64(#{WRTR_NM_ENCPT}) /*작성자명*/ , #{CNTN_IP_ADDR} /*아이피*/ , #{RETE_CN} /*답글내용*/ , #{BBSCTT_ESNTAL_NO} /*게시글번호*/ , '15' /*게시글유형구분코드*/ , AYE120_SQ01.NEXTVAL /*답글고유번호*/ , #{RETE_TTL_NM} /*답글제목*/
, #{ATFINO} /*첨부파일명*/
)

mapper.update:
UPDATE AYE120 SET 
            /*SQL-ID : isry.couns.constt.medscsnntabrd.mapper.BbsmomListMapper :  자녀맘터치법(답글수정)*/
            RETE_CN = #{RETE_CN}
           ,LAST_MDFR_ID = #{LAST_MDFR_ID}                    
           ,LAST_MDFCN_DT = SYSDATE                             
WHERE      1=1
    AND     BBSCTT_TYPE_SE_CD = '15'
    AND     BBSCTT_ESNTAL_NO = #{BBSCTT_ESNTAL_NO__origin}
    AND     RETE_ESNTAL_NO = #{RETE_ESNTAL_NO__origin}

UPDATE AYE120 SET
            /*SQL-ID : isry.couns.constt.medscsnntabrd.mapper.BbsmomListMapper :  자녀맘터치법(답글삭제)*/
              DEL_YN = 'Y'
            , LAST_MDFCN_DT = SYSDATE     
            , LAST_MDFR_ID = #{LAST_MDFR_ID}
WHERE       1=1
    AND     BBSCTT_TYPE_SE_CD = '15'
    AND     BBSCTT_ESNTAL_NO = #{BBSCTT_ESNTAL_NO__origin}
    AND     RETE_ESNTAL_NO = #{RETE_ESNTAL_NO__origin}

UPDATE  /* isry.couns.constt.medscsnntabrd.mapper.BbscttListMapper.updateMemo : 자녀맘터치법 메모수정 */
        AYA160
SET
        MEMO_NM                 =       #{MEMO_NM}
    ,   LAST_MDFR_ID            =       #{LAST_MDFR_ID}
    ,   LAST_MDFCN_DT           =       SYSDATE
WHERE   1=1
    AND BBSCTT_ESNTAL_NO        =       #{BBSCTT_ESNTAL_NO}
    AND BBSCTT_TYPE_SE_CD       =       '15'
